var host="lesis.lat";if(window.location.host==host&&window.location.protocol!="https:"){window.location.protocol="https:"}var modal=document.getElementById("contactModal"),btn=document.getElementById("contactBtn"),span=document.getElementsByClassName("close")[0];btn.onclick=function(){modal.style.display="block"};span.onclick=function(){modal.style.display="none"};window.onclick=function(e){if(e.target==modal){modal.style.display="none"}};var contactLink=document.getElementById("contactLink");contactLink.onclick=function(e){e.preventDefault();modal.style.display="block"};const hamburger=document.getElementById("hamburgerIcon"),menu=document.querySelector("nav ul");hamburger.addEventListener("click",function(){hamburger.classList.toggle("open");menu.classList.toggle("show")});
